  #[local] Abbreviation C := (fun r : reg => In r memset_clob) (only parsing).

  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Lemma p1_ret : forall regs l,
    getr regs 1 = ret -> getr regs 12 = Z_to_bv 64 n -> getr regs 14 = Z_to_bv 64 3 -> (n <= 2)%Z ->
