  Ltac agreeC H := first [ exact H | regs_agree_weaken H ].
  Ltac chainC :=
    lazymatch goal with
    | |- regs_agree _ ?a ?a => apply regs_agree_refl
    | H : regs_agree _ ?m ?c |- regs_agree _ ?a ?c =>
        first [ agreeC H | eapply (regs_agree_trans _ a m c); [ clear H; chainC | agreeC H ] ]
    end.

